If `result.structured_reasons` is a non-array object, `result.structured_reasons ?? []` will evaluate to that object, and calling `.map` on it will throw a `TypeError`. Use `Array.isArray` to safely default to an empty array.

```javascript
function reasonCodesFromResult(result) {
  const reasons = Array.isArray(result?.structured_reasons) ? result.structured_reasons : [];
  return uniqueSorted(reasons.map((reason) => reason?.code));
}

function reasonFamiliesFromResult(result) {
  const reasons = Array.isArray(result?.structured_reasons) ? result.structured_reasons : [];
  return uniqueSorted(reasons.map((reason) => reason?.family));
}
```

