When validating expected array fields in input data, if a field is present but is not an array, record a validation failure (blocker) and process it as an empty array. This prevents TypeErrors during execution while ensuring the system fails closed.

```javascript
function buildReviewTasks({ inputs, paths, rubric, diagnostics = [] }) {
  const validatorTasks = queueableValidatorResults(inputs.triangulationValidatorResult)
    .map(({ result, resultKind, resultIndex }) => buildValidatorReviewTask({
      result,
      resultKind,
      resultIndex,
      paths,
      rubric,
    }));
  let taxonomyTasks = [];
  const reviewTasks = inputs.taxonomyReviewQueue?.review_tasks;
  if (reviewTasks !== undefined) {
    if (!Array.isArray(reviewTasks)) {
      diagnostics.push({
        code: 'invalid_array_field',
        message: 'review_tasks is not an array',
        severity: 'blocker',
      });
    } else {
      taxonomyTasks = reviewTasks
        .filter((task) => task !== null && task !== undefined)
        .map((task, taskIndex) => buildTaxonomyReviewTask({
          task,
          taskIndex,
          paths,
          rubric,
        }));
    }
  }

  return [...validatorTasks, ...taxonomyTasks]
    .sort((left, right) => compareByteOrder(left.review_task_id, right.review_task_id));
}
```

